// Normalize Google Sheets headers (case, spaces, punctuation) and Facebook fields.
const keyNorm = value => String(value).toLowerCase().replace(/[^a-z0-9]/g, '');
const first = (data, ...keys) => {
  for (const key of keys) {
    const match = Object.entries(data).find(([column]) => keyNorm(column) === keyNorm(key));
    const value = match?.[1];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
  }
  return '';
};
const facebookField = (fields, name) => fields.find(field => keyNorm(field.name) === keyNorm(name))?.values?.[0] || '';
const items = [];
for (const item of $input.all()) {
  const data = item.json;
  let leadData;
  if (data.leadgen_id || data.form_id) {
    const fields = data.field_data || [];
    leadData = {
      name: first(data, 'name', 'full_name') || facebookField(fields, 'full_name'),
      email: first(data, 'email', 'email_address') || facebookField(fields, 'email'),
      phone: first(data, 'phone', 'phone_number') || facebookField(fields, 'phone_number'),
      job_title: first(data, 'job_title', 'title') || facebookField(fields, 'job_title'),
      company: first(data, 'company', 'company_name', 'organization') || facebookField(fields, 'company_name'),
      comments: first(data, 'comments', 'notes') || facebookField(fields, 'comments'),
      company_website: first(data, 'company_website', 'company_domain', 'website'),
      industry: first(data, 'industry', 'sector', 'column 8'),
      linkedin_url: first(data, 'linkedin_url', 'linkedin_profile_url'),
      interest_area: first(data, 'interest_area', 'area_of_interest'),
      challenge: first(data, 'challenge', 'biggest_challenge'),
      company_size: first(data, 'company_size'),
      country: first(data, 'country', 'location'),
      source: 'facebook',
      source_columns: Object.keys(data)
    };
  } else {
    const firstName = first(data, 'first_name', 'first name');
    const lastName = first(data, 'last_name', 'last name');
    leadData = {
      name: first(data, 'name', 'full_name', 'contact_name', 'lead_name', 'name of lead', 'column 2') || [firstName, lastName].filter(Boolean).join(' '),
      email: first(data, 'email', 'email_address', 'work_email', 'business_email', 'contact_email', 'email_id', 'gmail', 'column 3'),
      phone: first(data, 'phone', 'phone_number', 'phone number', 'mobile', 'mobile number', 'column 6'),
      job_title: first(data, 'job_title', 'job title', 'job tittle', 'job title role', 'role', 'position', 'title', 'column 7'),
      company: first(data, 'company', 'company_name', 'company name', 'organization', 'organisation', 'account name', 'business name', 'employer', 'column 4'),
      company_website: first(data, 'company_website', 'company domain', 'company website', 'website'),
      comments: first(data, 'comments', 'comment', 'notes', 'message'),
      industry: first(data, 'industry', 'sector', 'column 8'),
      linkedin_url: first(data, 'linkedin_url', 'linkedin profile url', 'linkedin profile url optional'),
      interest_area: first(data, 'interest_area', 'area of interest', 'what area are you most interested in', 'column 9'),
      challenge: first(data, 'challenge', 'biggest challenge', "what's your biggest challenge right now", 'what is your biggest challenge right now', 'column 10'),
      company_size: first(data, 'company_size', 'company size', 'column 11'),
      country: first(data, 'country', 'location'),
      source: 'google_sheets',
      source_columns: Object.keys(data)
    };
  }
  items.push({ json: leadData });
}
return items;
